import html2pdf from "html2pdf.js";

export const exportRegistrationsPDF = async (eventName, distances, distanceRows) => {
    let rows = "";

    distances.forEach(distance => {
        const distanceId = distance.id;
        const registrations = distanceRows[distanceId] || [];

        registrations.forEach(reg => {
            const boatSize = distance.Boat?.amount_of_people || 1;

            for (let i = 1; i <= boatSize; i++) {
                const key = i === 1 ? "participant_id" : `participant_id${i}`;
                const participant = reg[key];

                if (participant) {
                    rows += `
                        <tr>
                            <td style="padding: 6px">${distance.Gender?.gender ?? ""}</td>
                            <td style="padding: 6px">${distance.Categories?.category ?? ""}</td>
                            <td style="padding: 6px">${distance.distance}</td>
                            <td style="padding: 6px">${distance.Boat?.boat ?? ""}</td>
                            <td style="padding: 6px">${reg.id}</td>
                            <td style="padding: 6px">${i}</td>
                            <td style="padding: 6px">${participant.first_name} ${participant.last_name}</td>
                        </tr>
                    `;
                }
            }
        });
    });

    const html = `
        <div style="font-family: Arial, sans-serif; padding:20px;">
            <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 12px" >
                <img style="width: 32px; height: 32px;" src="data:image/png;base64," alt="Klokking"/>
                <h3>Inschrijvingen ${ isNaN(eventName) ? `voor ${eventName}` : ``}</h3>
            </div>
            <p style="font-size: 12px">Deelnemers van andere verenigingen worden niet weergegeven in verband met privacy.</p>            
            <table style="width:100%; border-collapse: collapse; font-size:12px;">
                <thead>
                    <tr style="background:#f2f2f2;">
                        <th style="padding:6px; text-align:left; border-bottom:1px solid #999;">Geslacht</th>
                        <th style="padding:6px; text-align:left; border-bottom:1px solid #999;">Categorie</th>
                        <th style="padding:6px; text-align:left; border-bottom:1px solid #999;">Afstand</th>
                        <th style="padding:6px; text-align:left; border-bottom:1px solid #999;">Boot</th>
                        <th style="padding:6px; text-align:left; border-bottom:1px solid #999;">Boot ID</th>
                        <th style="padding:6px; text-align:left; border-bottom:1px solid #999;">Plaats</th>
                        <th style="padding:6px; text-align:left; border-bottom:1px solid #999;">Deelnemer</th>
                    </tr>
                </thead>

                <tbody>
                    ${rows}
                </tbody>
            </table>
        </div>
    `;

    await html2pdf()
        .set({
            margin: 10,
            filename: `Inschrijvingen-Klokking-${eventName}.pdf`,
            html2canvas: { scale: 2 },
            jsPDF: { unit: "mm", format: "a4", orientation: "portrait" }
        })
        .from(html)
        .save();
};